mapper.select:
SELECT post_id FROM post
WHERE post_id > #{lastId}
ORDER BY post_id
LIMIT #{limit}

SELECT p.post_id AS post_id, p.review_round AS review_round
FROM post p
WHERE p.state = 'PENDING_REVIEW'
  AND p.review_entered_at IS NOT NULL
  AND p.review_entered_at <= #{before}
LIMIT #{limit}

SELECT 
FROM post p
WHERE p.user_id = #{userId}
  AND p.state IN ('NORMAL', 'PENDING_REVIEW', 'DRAFT', 'REJECTED')
ORDER BY p.create_time DESC, p.post_id DESC
LIMIT #{offset}, #{limit}

SELECT 
FROM post p
WHERE p.user_id = #{userId}
  AND p.state = 'NORMAL'
ORDER BY p.create_time DESC, p.post_id DESC
LIMIT #{offset}, #{limit}
